const map = <A, B>(xs: readonly A[], f: (a: A) => B): B[] =>
	xs.reduce<B[]>((acc, x) => [...acc, f(x)], []);

const filter = <A>(xs: readonly A[], keep: (a: A) => boolean): A[] =>
	xs.reduce<A[]>((acc, x) => (keep(x) ? [...acc, x] : acc), []);

